style.css:
@-moz-document domain("roblox.com") {
/* Deja pasar tu imagen de fondo a través de los paneles internos */
  #rbx-body > div, .content, .rbx-body, main, #home-container, .page-content,
  .light-theme, .dark-theme, [class*="content"], [class*="container-main"] {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Barra superior y menú lateral en celeste claro translúcido */
  #header, .rbx-header {
    background-color: rgba(185, 229, 255, 0.88) !important;
    border-bottom: 1px solid rgba(114, 185, 235, 0.5) !important;
  }

  .rbx-left-col {
    background-color: rgba(240, 249, 255, 0.85) !important;
    backdrop-filter: blur(5px);
  }

  /* Tarjetas y secciones en blanco semitransparente (modo claro) */
  .section-content, .game-card-container, .stack-row, .profile-header-content,
  .rbx-tabs-horizontal .rbx-tab-heading, [class*="game-card"] {
    background-color: rgba(255, 255, 255, 0.78) !important;
    backdrop-filter: blur(4px);
    border-radius: 10px !important;
  }

  /* Textos oscuros bien legibles */
  body, h1, h2, h3, h4, .text-name, .game-card-name, .rbx-text-navbar-right, .font-header-2 {
    color: #1e3a5f !important;
  }
}
